public enum Permission {
    READ, WRITE, EXECUTE, ADMIN
}

public class PermissionEngine {
    // EnumSet replaces bitmasks with type-safe operations
    private final EnumSet<Permission> activePermissions = EnumSet.of(Permission.READ, Permission.WRITE);

    // EnumMap replaces cumbersome switches or HashMap lookups
    private final EnumMap<Permission, String> auditLog = new EnumMap<>(Permission.class);

    public void configureAccess() {
        auditLog.put(Permission.READ, "Read access granted to user.");
        auditLog.put(Permission.WRITE, "Write access granted to user.");

        if (activePermissions.contains(Permission.WRITE)) {
            System.out.println(auditLog.get(Permission.WRITE));
        }
    }
}
